import{_ as i,l as n,o as e,c as l,v as r,p as s,x as t,d as E,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"缺失市场","description":"","frontmatter":{"title":"缺失市场","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/missing-markets.md","filePath":"econ/missing-markets.md","lastUpdated":1789023840000}'),d={name:"econ/missing-markets.md"};function A(c,a,m,B,_,f){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="缺失市场" tabindex="-1">缺失市场 <a class="header-anchor" href="#缺失市场" aria-label="Permalink to &quot;缺失市场&quot;">​</a></h1><div class="epigraph"><p>外部性之所以使竞争失灵，是因为影响别人的那一维商品根本没有被拿到市场上定价。</p><footer>—— 据 Arrow, The Organization of Economic Activity, 1969；Mas-Colell, Whinston and Green, Microeconomic Theory, 第 11 章 整理</footer></div><p><a href="/econ/externality-pigou">上一课</a>把外部性写成私人边际与社会边际分叉，并用庇古税把 \\(\\mathrm{MD}(q^*)\\) 塞回一阶条件。缺口是商品空间语言：为什么会有这项看不见的边际？Arrow 的诊断是缺了一列市场。本课把「市场失灵」收成「列表不全」，不重写 \\(\\mathrm{MD}\\) 曲线，也不预支科斯谈判。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/welfare-theorems">第一福利定理</a>的会计用到：凡进入别人效用或生产的东西，都进了某个人的预算。若排放 \\(e\\) 被写成带价格 \\(p_e\\) 的商品，竞争均衡再次有效——问题退回完整市场。缺这个市场，不是 \\(p_e=0\\) 的均衡，而是根本没有报价：\\(e\\) 不在可行交易集里。私人决策的一阶条件少一项，正是上一课的分叉。</p><p>金钱外部性只改价格，已经在瓦尔拉斯会计里，第一定理仍成立。技术外部性才是漏列：别人的行动作为自变量出现，却不作为商品出现。Meade 的养蜂与果园，是同一句话的教具：蜜与花粉若能按单位交易，就不是外部性。</p><h3 id="缺市场不是「市场太少」的口号" tabindex="-1">缺市场不是「市场太少」的口号 <a class="header-anchor" href="#缺市场不是「市场太少」的口号" aria-label="Permalink to &quot;缺市场不是「市场太少」的口号&quot;">​</a></h3><p>完整与否相对于事先写好的商品空间。或有商品按状态列全，是<a href="/econ/state-contingent">状态依存</a>的完全；排放按地点、时间列全，是另一份清单。清单漏了，核同样说不清「联盟走开时污染跟不跟」。庇古税、可交易许可、产权，都是事后给漏列的那一维指定影子价格或可转让禀赋。</p><p><span class="marginnote">MWG 把技术外部性定义为：某个决策者的选择直接进入另一人的目标或约束，且没有对应的价格。诊断在商品空间，治疗可以是税、配额或把该维补进市场。三者在完全信息、凸性下对准同一影子价格。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：把上一课的 \\(e\\) 明确写成未上市商品。对照三种补法——扩维开市场、从量税、数量配额——完全信息下对准同一 \\(q^*\\)。本课钉诊断：失灵写在「哪一列不存在」，不钉税率公式。</p><p>缺失市场也覆盖公共品的极限：非竞争使「每人买自己的那一份」没有定义，市场不是漏一列，是漏了一种加总方式。那一课再写；这里只要记住：私人品漏列与公共品漏列，都是商品空间的病，不是偏好的病。</p>',12)),(e(),s(h,null,{default:t(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FULL%5B%22%E5%95%86%E5%93%81%E5%88%97%E5%85%A8%EF%BC%9A%E7%AC%AC%E4%B8%80%E5%AE%9A%E7%90%86%22%5D%20--%3E%20MISS%5B%22%E6%BC%8F%E5%88%97%20e%EF%BC%9A%E6%97%A0%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20MISS%20--%3E%20EXT%5B%22%E6%8A%80%E6%9C%AF%E5%A4%96%E9%83%A8%E6%80%A7%22%5D%0A%20%20EXT%20--%3E%20PIG%5B%22%E5%BA%87%E5%8F%A4%EF%BC%9A%E5%BD%B1%E5%AD%90%E4%BB%B7%E6%A0%BC%E5%BD%93%E7%A8%8E%22%5D%0A%20%20EXT%20--%3E%20MKT%5B%22%E8%A1%A5%E5%B8%82%E5%9C%BA%EF%BC%9A%E6%8A%8A%20e%20%E4%B8%8A%E5%B8%82%22%5D%0A%20%20EXT%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%BA%A7%E6%9D%83%E6%8A%8A%E5%B8%82%E5%9C%BA%E9%95%BF%E5%87%BA%E6%9D%A5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么漏列会拆有效性：帕累托改进可以只改那一维未定价的行动，加总财富不必上升，第一定理的「更好则更贵」戳不破。竞争均衡仍可以存在，只是有效性掉了。存在性与有效性本来就不是同一句话：<a href="/econ/ge-existence">存在</a>不保证清单齐全。</p><p>与<a href="/econ/incomplete-markets-gei">不完全市场 GEI</a>的差别：GEI 是或有证券张成不足，商品名字还在，只是不能自由组合；本课是名字根本没列。太阳黑子是外在信念钻进未保险的方向；外部性是别人的烟钻进效用。不要并成一句「市场不完全」。</p><p>配额与税在完全信息下对准同一影子价格，并不取消「列缺了」这一诊断：工具改变的是私人一阶条件，不是把 \\(e\\) 写进商品空间。科斯谈判若成功，才真的把那一列补进可转让禀赋。</p><h3 id="补列与征税在信息上同构" tabindex="-1">补列与征税在信息上同构 <a class="header-anchor" href="#补列与征税在信息上同构" aria-label="Permalink to &quot;补列与征税在信息上同构&quot;">​</a></h3><p>计划者要知道有效点上的 \\(\\mathrm{MD}\\)，开市场的人要知道需求，都是同一信息。缺市场理论不自动给出可观察的税基。后课科斯把信息问题换成谈判成本：若权利清晰、人少，市场可以「长出来」，不必先算出 \\(t\\)。人多、非排他，市场长不出来，公共品接手。</p><p><span class="marginnote">金钱外部性（某商品涨价伤害买方）已经通过预算进入每人的问题，再征一笔「涨价税」是叠扭曲。漏列诊断只针对技术外部性。股价、工资变动默认走价格，不走本课。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>非凸、不可分、不完全信息，都可以在市场列全时仍失灵；缺市场不是失灵的全集。公共品、逆向选择是后课的另一些缺口。也不要把缺市场写成限价簿「某合约未挂牌」——本栏是商品空间，不是订单队列。科斯将问：权利清晰时，漏列的那一维能不能由私人谈判补上。</p><p>Arrow–Debreu 把商品写成（物理、时间、地点、事件）。漏列可以发生在任何一维：没有「明天下雨的伞」是或缺有状态，没有「邻居的安静」是或缺有事件上的权利。清单写全，第一定理的假设才齐；写不全，税与产权都是补清单的办法。</p><p>后课默认：技术外部性 = 漏列的或有（或实物）商品；一阶纠正是给那一列一个影子价格。产权能否把该列变成可交易禀赋，是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>第一定理要求影响别人的那一维进入预算；漏列即技术外部性。</li><li>缺市场是诊断；税、配额、开盘是对准同一影子价格的补法。</li><li>金钱外部性已在价格里，不是漏列。</li><li>GEI 是张成不足；本课是名字未列。</li><li>出处：Arrow, 1969；Meade, 1952；Mas-Colell, Whinston and Green, 第 11 章。</li></ul>',13))])}const C=i(d,[["render",A]]);export{T as __pageData,C as default};
